using System.Text.Json;
namespace StarlightSyndicateDemo;
internal static class FittingSimulationTests
{
 public static void Run(){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception("FAIL: "+label);checks++;Console.WriteLine("PASS: "+label);}
 string State(DemoWorld w)=>JsonSerializer.Serialize(new{w.Player,w.Credits,w.Day,w.SystemId,w.Grid,w.Screen,w.CargoItems,w.StationItems,w.FleetBerths},WeaponCatalog.JsonOptions);
 bool testedHullSwitches=false;
 foreach(var hull in FleetCatalog.Playable){var live=new DemoWorld();live.NewGame(0);live.Credits=1000000;live.SystemId=ShipBatch21.ById[hull.Id].HomeSystem;Check(live.BoardFleetHull(hull.Id),"Acquire actual simulation fixture / "+hull.Name);live.Screen=ViewMode.Space;live.Player.Weapons[0].Active=true;var before=State(live);var sim=new FittingSimulation(live.Player);Check(!ReferenceEquals(sim.World.Player,live.Player)&&!ReferenceEquals(sim.World.Player.Attributes,live.Player.Attributes),"Detached ship and attributes / "+hull.Name);Check(sim.World.Player.HullName==live.Player.HullName&&sim.World.Player.CombatHull==live.Player.CombatHull,"Hull identity retained");Check(sim.World.Player.Attributes.SequenceEqual(live.Player.Attributes),"Exact source attributes retained / "+hull.Name+" / "+string.Join(",",sim.World.Player.Attributes.Where(a=>a.Value!=live.Player.Attributes[a.Key]).Select(a=>a.Key+":"+a.Value+"/"+live.Player.Attributes[a.Key])));Check(sim.World.Player.Weapons.All(w=>!w.Active),"Copied cycles stopped");
 var module=FittingLayoutModel.Installed(sim.World.Player).FirstOrDefault();if(module!=null){sim.SetActive(module,true);Check(sim.World.Player.CapacitorUse>=0,"Finite assumed module capacitor");Check(State(live)==before,"Cycle assumption leaves campaign unchanged");sim.SetActive(module,false);switch(module.Kind){case "weapon":sim.World.UnfitLayoutWeapon(module.Index);break;case "defense":sim.World.UnfitDefense(module.Index);break;case "support":sim.World.UnfitSupport(module.Index);break;case "mobility":sim.World.UnfitMobility(module.Index);break;case "utility":sim.World.UnfitUtility(module.Index);break;case "special":sim.World.UnfitSpecial(module.Index);break;}sim.Stock();var spec=FittingLayoutModel.ById[module.Id];int slot=FittingLayoutModel.Destination(sim.World.Player,spec);Check(FittingLayoutModel.Fit(sim.World,spec,true,slot),"Free simulation refit uses native rules");Check(State(live)==before,"Refit leaves campaign unchanged");}else Check(FittingLayoutModel.Installed(sim.World.Player).Count==0,"Empty source fitting preserved");
 sim.Reset(live.Player);Check(sim.World.Player.Weapons[0].ModuleId==live.Player.Weapons[0].ModuleId,"Reset restores live fit");if(!testedHullSwitches){foreach(var h in FleetCatalog.Playable){sim.Hull(h.Id);Check(sim.World.Player.CombatHull==h.Id,"Simulated hull switch / "+h.Name);}testedHullSwitches=true;}Check(State(live)==before,"Hull switches leave campaign unchanged");
 sim.World.Player.SetStat("cpuOutput",1);var candidate=FittingLayoutModel.Catalog.First(d=>d.Kind=="weapon"&&d.Cpu>1);Check(FittingLayoutModel.Error(sim.World,candidate,0).Length>0,"Invalid CPU fit rejected");Check(State(live)==before,"Rejected fit leaves campaign unchanged");}
 Console.WriteLine($"Fitting simulation: {checks} checks passed.");}
}
